func TestGetReturnsSavedRows(t *testing.T) {
	service := NewService(&fakeRepo{json: `{"columns":[{"name":"a"}],"rows":[{"a":1},{"a":2}]}`}, nil)
	detail, err := service.Get(context.Background(), 7, 1, true)
	if err != nil {
