// 결과 값(사용자 데이터)을 SQL 리터럴로 만드는 helper 입니다.
// 외래키 이동처럼 셀 값을 SQL 에 그대로 넣는 경로가 있어, 인용·이스케이프 규칙을
// 한곳에 모아 두고 테스트로 고정합니다(`node test/js/sqlvalue.test.mjs`).

// sqlLiteral 은 값을 SQL 리터럴 문자열로 바꿉니다. 값을 넣을 수 없으면 null 을 돌려주고,
// 호출부는 그 경우 동작을 제공하지 않습니다(예: NULL 셀에서는 이동 메뉴를 감춤).
export function sqlLiteral(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'number') return Number.isFinite(value) ? String(value) : null;
  if (typeof value === 'boolean') return value ? '1' : '0';
  const text = typeof value === 'object' ? JSON.stringify(value) : String(value);
  // 숫자로만 이루어진 문자열도 따옴표를 씌웁니다. 문자형 키를 숫자로 넘기면 방언에 따라
  // 암시적 변환이 일어나 인덱스를 못 타거나 결과가 달라집니다.
  // 작은따옴표는 반드시 중복 이스케이프합니다(값은 사용자 데이터입니다).
  return `'${text.replaceAll("'", "''")}'`;
}
