  const el = document.querySelector('#version-info');
  if (!el) return;
  try {
    const response = await fetch('/api/v1/system/info', { headers: { Accept: 'application/json' } });
    if (!response.ok) return;
    const body = await response.json();
    const product = (body.data && body.data.product) || 'DartFly';
    const version = (body.data && body.data.version) || '';
    el.textContent = version ? `${product} ${version}` : product;
    // SSO 활성화 시 버튼 표시
    if (body.data && body.data.sso_enabled) {
      const block = document.querySelector('#sso-block');
      const btn = document.querySelector('#sso-login');
      if (btn && body.data.sso_label) btn.textContent = body.data.sso_label;
      if (btn) btn.href = `/auth/sso/login?return_to=${encodeURIComponent(returnTo)}`; // 버튼으로 들어가도 그 자리로
      if (block) block.hidden = false;
