func hexPreview(raw []byte) string {
	if len(raw) <= binaryPreviewBytes {
		return "0x" + strings.ToUpper(hex.EncodeToString(raw))
	}
	return fmt.Sprintf("0x%s…(총 %d바이트)",
		strings.ToUpper(hex.EncodeToString(raw[:binaryPreviewBytes])), len(raw))
}

