// 저장 결과는 executed_sql_resource(result_save_yn='YES', types='SAVE')에 메타를,
// executed_sql_result_data에 결과 JSON을, executed_sql_resource_data에 SQL을 보관합니다.

func (s *Store) InsertSavedResult(ctx context.Context, userID, dbSeq int64, sqlText, resultJSON string, rowCount int) (resultsave.Saved, error) {
	tx, err := s.DB.BeginTx(ctx, nil)
	if err != nil {
		return resultsave.Saved{}, err
	}
	defer tx.Rollback()
	now := time.Now().UTC()
	result, err := tx.ExecContext(ctx, `INSERT INTO executed_sql_resource
		(startdateexecute, user_seq, db_seq, types, enddateexecute, duration, `+"`row`"+`, result, tdb_result_code, delyn, result_save_yn, create_time)
		VALUES (?, ?, ?, 'SAVE', ?, 0, ?, 'YES', 200, 'NO', 'YES', UTC_TIMESTAMP())`, now, userID, dbSeq, now, rowCount)
	if err != nil {
		return resultsave.Saved{}, fmt.Errorf("결과 저장(메타): %w", err)
	}
	id, _ := result.LastInsertId()
	if _, err := tx.ExecContext(ctx, `INSERT INTO executed_sql_resource_data (startdateexecute, executed_sql_resource_seq, sql_type, schema_name, sql_data, ctreate_time) VALUES (?, ?, 'SAVE', '', ?, UTC_TIMESTAMP())`, now, id, sqlText); err != nil {
		return resultsave.Saved{}, fmt.Errorf("결과 저장(SQL): %w", err)
	}
	if err := checkResultFits(ctx, tx, len(resultJSON)); err != nil {
		return resultsave.Saved{}, err
	}
	if _, err := tx.ExecContext(ctx, `INSERT INTO executed_sql_result_data (startdateexecute, executed_sql_resource_seq, result_data, ctreate_time) VALUES (?, ?, ?, UTC_TIMESTAMP())`, now, id, resultJSON); err != nil {
		return resultsave.Saved{}, fmt.Errorf("결과 저장(데이터): %w", err)
	}
	if err := tx.Commit(); err != nil {
		return resultsave.Saved{}, err
	}
	return resultsave.Saved{ID: id, DBSeq: dbSeq, UserSeq: userID, SQL: sqlText, RowCount: rowCount, CreatedAt: now}, nil
}

const savedSelect = `
	SELECT r.seq, COALESCE(r.db_seq,0), COALESCE(d.display_name, d.db, ''), COALESCE(r.user_seq,0), COALESCE(u.name, u.email, ''),
	       COALESCE((SELECT sql_data FROM executed_sql_resource_data sd WHERE sd.executed_sql_resource_seq = r.seq ORDER BY sd.seq LIMIT 1), ''),
	       r.` + "`row`" + `, r.startdateexecute
	FROM executed_sql_resource r
	LEFT JOIN tadpole_db d ON d.seq = r.db_seq
	LEFT JOIN tadpole_user u ON u.seq = r.user_seq
	WHERE r.result_save_yn='YES' AND r.delyn='NO'`

func scanSaved(scanner interface{ Scan(...any) error }) (resultsave.Saved, error) {
	var item resultsave.Saved
	var rowCount int64
	if err := scanner.Scan(&item.ID, &item.DBSeq, &item.DBName, &item.UserSeq, &item.UserName, &item.SQL, &rowCount, &item.CreatedAt); err != nil {
		return resultsave.Saved{}, err
	}
	item.RowCount = int(rowCount)
	return item, nil
}

func (s *Store) ListSavedResults(ctx context.Context, userID int64, admin bool, limit, offset int) ([]resultsave.Saved, int64, error) {
	var total int64
	if err := s.DB.QueryRowContext(ctx, `SELECT COUNT(*) FROM executed_sql_resource r WHERE r.result_save_yn='YES' AND r.delyn='NO' AND (? OR r.user_seq = ?)`, admin, userID).Scan(&total); err != nil {
		return nil, 0, fmt.Errorf("저장 결과 개수: %w", err)
	}
	rows, err := s.DB.QueryContext(ctx, savedSelect+` AND (? OR r.user_seq = ?) ORDER BY r.seq DESC LIMIT ? OFFSET ?`, admin, userID, limit, offset)
	if err != nil {
		return nil, 0, fmt.Errorf("저장 결과 조회: %w", err)
	}
	defer rows.Close()
	items := make([]resultsave.Saved, 0)
	for rows.Next() {
		item, err := scanSaved(rows)
		if err != nil {
			return nil, 0, err
		}
		items = append(items, item)
	}
	return items, total, rows.Err()
}

func (s *Store) GetSavedResult(ctx context.Context, id, userID int64, admin bool) (resultsave.Saved, string, error) {
	row := s.DB.QueryRowContext(ctx, savedSelect+` AND r.seq = ? AND (? OR r.user_seq = ?)`, id, admin, userID)
	meta, err := scanSaved(row)
	if errors.Is(err, sql.ErrNoRows) {
		return resultsave.Saved{}, "", errors.New("저장된 결과를 찾을 수 없거나 권한이 없습니다")
	}
	if err != nil {
		return resultsave.Saved{}, "", err
	}
	var resultJSON sql.NullString
	if err := s.DB.QueryRowContext(ctx, `SELECT result_data FROM executed_sql_result_data WHERE executed_sql_resource_seq = ? ORDER BY seq LIMIT 1`, id).Scan(&resultJSON); err != nil && !errors.Is(err, sql.ErrNoRows) {
		return resultsave.Saved{}, "", fmt.Errorf("저장 결과 데이터 조회: %w", err)
	}
	return meta, resultJSON.String, nil
}

func (s *Store) DeleteSavedResult(ctx context.Context, id, userID int64, admin bool) error {
	result, err := s.DB.ExecContext(ctx, `UPDATE executed_sql_resource SET delyn='YES', result_del_user_seq=?, result_del_time=UTC_TIMESTAMP() WHERE seq=? AND result_save_yn='YES' AND delyn='NO' AND (? OR user_seq = ?)`, userID, id, admin, userID)
	if err != nil {
		return fmt.Errorf("저장 결과 삭제: %w", err)
	}
	if affected, _ := result.RowsAffected(); affected == 0 {
		return errors.New("저장된 결과를 찾을 수 없거나 권한이 없습니다")
	}
	return nil
}

// packetOverheadBytes는 INSERT 문에서 결과 JSON 말고 나머지가 차지하는 여유분입니다.
// 컬럼 이름·자리표시자·프로토콜 머리말을 넉넉히 잡습니다.
const packetOverheadBytes = 4096

// checkResultFits는 결과 JSON 이 메타 DB 가 한 번에 받는 크기 안에 드는지 먼저 봅니다.
//
// 그냥 넣어 보고 실패를 해석하는 방법은 통하지 않았습니다. 실측했습니다. 같은
// 20MB 결과를 저장했을 때 한 번은
//
//	Error 1153 (08S01): Got a packet bigger than 'max_allowed_packet' bytes
//
// 가 왔고, 다른 때는 서버가 먼저 연결을 끊어
//
//	write tcp 127.0.0.1:52184->127.0.0.1:53307: write: broken pipe
//
// 가 왔습니다. 뒤쪽은 무엇이 문제인지 알 수 없을 뿐 아니라 메타 DB 주소가 그대로
// 화면까지 나갑니다. 어느 쪽이 오는지는 우리가 정할 수 없으므로, 넣기 전에 재서
// 늘 같은 안내를 내보냅니다.
func checkResultFits(ctx context.Context, tx *sql.Tx, size int) error {
	var limit int
	if err := tx.QueryRowContext(ctx, `SELECT @@max_allowed_packet`).Scan(&limit); err != nil || limit <= 0 {
		return nil // 한도를 못 읽으면 막지 않습니다. 그때는 예전처럼 드라이버 오류가 납니다.
	}
	if size+packetOverheadBytes <= limit {
		return nil
	}
	return fmt.Errorf("결과 저장(데이터): 결과가 %.1fMB 라 메타 DB 가 한 번에 받을 수 있는 크기(%.1fMB)를 넘습니다. 행 수를 줄여 저장하거나 관리자에게 max_allowed_packet 을 늘려 달라고 요청하세요",
		float64(size)/(1<<20), float64(limit)/(1<<20))
}
